fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Consider only first n participants or fewer if participations shorter
    let limit = n.min(participations.len() as u8) as usize;
    
    // Count eligible participants
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attendance| 5u8.saturating_sub(attendance) >= k)
        .count() as u8;
    
    // Number of teams is eligible_count divided by 3 (integer division)
    eligible_count / 3
}